   296	    private Double calculatePaymentAdjustment(CheckoutRequest request, Double subtotal) throws CheckoutException {
   297	        PaymentStrategy strategy = PaymentFactory.create(request.paymentMethod);
   298	
   299	        Integer installments = request.installments != null ? request.installments : 1;
   300	
   301	        if (!strategy.isApplicable(subtotal, installments)) {
   302	            throw new CheckoutException("PAYMENT_METHOD_UNAVAILABLE");
   303	        }
   304	
   305	        if (request.paymentMethod == PaymentMethod.PIX && request.coupon != null) {
   306	            return 0.0;
   307	        }
   308	
   309	        return strategy.calculateAdjustment(subtotal, installments);
   310	    }
